SELECT NVL(SUM(PLAN_MINUTES), 0)
  FROM TB_WORK_PLAN
 WHERE EMP_ID = #{employeeId}
   AND WORK_DATE = #{workDate}

SELECT COUNT(*) FROM TB_ATT_CORRECTION_REQ
 WHERE EMP_ID = #{employeeId}
   AND WORK_DATE = #{workDate}
   AND APPROVAL_STATUS = 'APPROVED'

